-- Sample "Grand Prix Results" dashboard (R500): a race weekend on two pages.
--
-- Page 1, the Brazilian Grand Prix (round 20 of 2026): the podium as cards,
-- the fastest lap, positions lap by lap (a rank chart drawn from the laps
-- where a position changed), the classified result with medal rows, each
-- driver's lap times against their own median in three-lap blocks, and where
-- each driver started against where they finished.
-- Page 2, the 2026 championships after that race: drivers' and constructors'
-- standings, the top three of each as cards, points as radial bars and as a
-- race over the season (each line in its team's colour and named at its
-- end), and the races left on the calendar.
--
-- Built in the dashboard editor and exported as it was saved: an always-dark
-- canvas with a faint red grid, frameless text blocks, red titles. Every
-- widget's SQL runs against the gp_* sample datasets
-- (src/assets/sample-data, made by scripts/buildGrandPrixSample.mjs from the
-- Jolpica F1 API, CC BY-NC-SA 4.0), and each carries the rows that SQL
-- returned, so the dashboard draws before anything is refreshed. Driver and
-- team badges and flags are drawn shapes, not photographs or logos.

INSERT INTO public.bi_sample_dashboards (sort, name, description, widgets, layout, pages, filters, theme)
VALUES (
  11,
  'Grand Prix Results · Sample',
  'A race weekend on two pages: the Brazilian Grand Prix podium, positions lap by lap, lap times against each driver''s median and places gained from the grid, then the 2026 drivers'' and constructors'' championships and the races left. Built on public Jolpica F1 data.',
  '[{"id":"gp_race_2","kind":"text","text":"# Brazilian Grand Prix\n*8 November 2026 · Round 20 of 23*","theme":{"card":"none","hideTitle":true},"title":"Race title","textStyle":{"size":"2xl","align":"center","color":"#ffffff","italic":true,"headingColor":"#e10600"}},{"id":"gp_race_1","kind":"text","text":"# GRAND PRIX\n**RESULTS · 2026**","theme":{"card":"none","hideTitle":true},"title":"Wordmark","textStyle":{"size":"xl","color":"#ffffff","italic":true,"headingColor":"#e10600"}},{"id":"gp_race_3","kind":"text","text":"### Autódromo José Carlos Pace\nSão Paulo, Brazil · 71 laps\n*First pit stops: laps 14–17*","theme":{"card":"none","hideTitle":true},"title":"Circuit","textStyle":{"align":"right","color":"#ffffff","headingColor":"#e10600"}},{"id":"gp_race_4","sql":"SELECT finish_position, given_name, family_name, team, race_time, points, badge, flag\nFROM gp_race_results\nWHERE finish_position <= 3\nORDER BY finish_position","kind":"chart","rows":[{"flag":"data:image/svg+xml;base64,","team":"McLaren","badge":"data:image/svg+xml;base64,","points":25,"race_time":"1:35:23.504","given_name":"Lando","family_name":"Norris","finish_position":1},{"flag":"data:image/svg+xml;base64,","team":"Red Bull","badge":"data:image/svg+xml;base64,","points":18,"race_time":"+14.602s","given_name":"Max","family_name":"Verstappen","finish_position":2},{"flag":"data:image/svg+xml;base64,","team":"Red Bull","badge":"data:image/svg+xml;base64,","points":15,"race_time":"+24.485s","given_name":"Isack","family_name":"Hadjar","finish_position":3}],"chart":{"body":"{{race_time}}\n**{{points}}** points","type":"cards","title":"{{given_name}} **{{family_name}}**","heading":"**{{finish_position|ordinal}}** Place","iconFields":["flag"],"imageField":"badge"},"theme":{"card":"none","accent":"#e10600","hideTitle":true},"title":"Podium","source":{"kind":"local"},"columns":["finish_position","given_name","family_name","team","race_time","points","badge","flag"],"truncated":false,"agg_pushdown":false,"refreshed_at":"2026-11-16T12:14:54.913+00:00"},{"id":"gp_race_5","sql":"SELECT ''Fastest Lap'' AS heading, given_name, family_name, team, fastest_lap_time, fastest_lap_number, points, badge, flag\nFROM gp_race_results\nWHERE fastest_lap_rank = 1","kind":"chart","rows":[{"flag":"data:image/svg+xml;base64,","team":"Mercedes","badge":"data:image/svg+xml;base64,","points":10,"heading":"Fastest Lap","given_name":"Andrea Kimi","family_name":"Antonelli","fastest_lap_time":"1:12.689","fastest_lap_number":55}],"chart":{"body":"{{fastest_lap_time}} (Lap {{fastest_lap_number}})\n**{{points}}** points","type":"cards","title":"{{given_name}} **{{family_name}}**","heading":"{{heading}}","imageField":"badge"},"theme":{"card":"none","accent":"#e10600","hideTitle":true},"title":"Fastest lap","source":{"kind":"local"},"columns":["heading","given_name","family_name","team","fastest_lap_time","fastest_lap_number","points","badge","flag"],"truncated":false,"agg_pushdown":false,"refreshed_at":"2026-11-16T12:16:13.126+00:00"},{"id":"gp_race_6","sql":"-- Positions lap by lap: the grid as lap 0, then only the laps where a\n-- driver''s position changed (and each driver''s last lap) — the chart holds\n-- a position until it changes.\nWITH p AS (\n  SELECT 0 AS lap, code, grid AS position, team_color FROM gp_race_results\n  UNION ALL\n  SELECT lap, code, position, team_color FROM gp_race_laps\n), k AS (\n  SELECT *, LAG(position) OVER (PARTITION BY code ORDER BY lap) AS prev,\n    LEAD(position) OVER (PARTITION BY code ORDER BY lap) AS nxt\n  FROM p\n)\nSELECT lap, code, position, team_color\nFROM k\nWHERE prev IS NULL OR nxt IS NULL OR position <> prev\nORDER BY lap, position","kind":"chart","rows":[{"lap":0,"code":"NOR","position":1,"team_color":"#FF8000"},{"lap":0,"code":"ANT","position":2,"team_color":"#27F4D2"},{"lap":0,"code":"LAW","position":3,"team_color":"#6692FF"},{"lap":0,"code":"HUL","position":4,"team_color":"#8A1538"},{"lap":0,"code":"HAD","position":5,"team_color":"#3671C6"},{"lap":