ver,\n  ROUND(LEAST(GREATEST(AVG(l.lap_seconds) - MAX(med.m), -1.5), 1.5), 2) AS vs_median\nFROM gp_race_laps l JOIN med USING (code)\nGROUP BY 1, 2, l.final_position\nORDER BY l.final_position, lap","kind":"chart","rows":[{"lap":1,"driver":"1. Norris","vs_median":1.5},{"lap":4,"driver":"1. Norris","vs_median":1.5},{"lap":7,"driver":"1. Norris","vs_median":1.5},{"lap":10,"driver":"1. Norris","vs_median":1.5},{"lap":13,"driver":"1. Norris","vs_median":1.5},{"lap":16,"driver":"1. Norris","vs_median":1.5},{"lap":19,"driver":"1. Norris","vs_median":1.5},{"lap":22,"driver":"1. Norris","vs_median":0.47},{"lap":25,"driver":"1. Norris","vs_median":-0.7},{"lap":28,"driver":"1. Norris","vs_median":-0.84},{"lap":31,"driver":"1. Norris","vs_median":-0.95},{"lap":34,"driver":"1. Norris","vs_median":-1.42},{"lap":37,"driver":"1. Norris","vs_median":-1.5},{"lap":40,"driver":"1. Norris","vs_median":-1.5},{"lap":43,"driver":"1. Norris","vs_median":-1.5},{"lap":46,"driver":"1. Norris","vs_median":-1.5},{"lap":49,"driver":"1. Norris","vs_median":1.5},{"lap":52,"driver":"1. Norris","vs_median":-1.5},{"lap":55,"driver":"1. Norris","vs_median":-1.5},{"lap":58,"driver":"1. Norris","vs_median":-1.13},{"lap":61,"driver":"1. Norris","vs_median":1.5},{"lap":64,"driver":"1. Norris","vs_median":1.5},{"lap":67,"driver":"1. Norris","vs_median":1.5},{"lap":70,"driver":"1. Norris","vs_median":1.5},{"lap":1,"driver":"2. Verstappen","vs_median":1.5},{"lap":4,"driver":"2. Verstappen","vs_median":1.5},{"lap":7,"driver":"2. Verstappen","vs_median":1.5},{"lap":10,"driver":"2. Verstappen","vs_median":1.5},{"lap":13,"driver":"2. Verstappen","vs_median":1.5},{"lap":16,"driver":"2. Verstappen","vs_median":1.5},{"lap":19,"driver":"2. Verstappen","vs_median":1.5},{"lap":22,"driver":"2. Verstappen","vs_median":-0.12},{"lap":25,"driver":"2. Verstappen","vs_median":-1.09},{"lap":28,"driver":"2. Verstappen","vs_median":-1.5},{"lap":31,"driver":"2. Verstappen","vs_median":-1.5},{"lap":34,"driver":"2. Verstappen","v