ON CONFLICT (name) DO UPDATE
  SET sort = EXCLUDED.sort,
      description = EXCLUDED.description,
      widgets = EXCLUDED.widgets,
      layout = EXCLUDED.layout,
      pages = EXCLUDED.pages,
      filters = EXCLUDED.filters,
      theme = EXCLUDED.theme;

-- Existing accounts get this one sample. Only this one: running the general
-- seed here would also bring back any sample an owner has deleted.
INSERT INTO public.bi_dashboards (user_id, name, description, widgets, layout, pages, filters, theme)
SELECT u.id, s.name, s.description, s.widgets, s.layout, s.pages, s.filters, s.theme
FROM auth.users u
CROSS JOIN public.bi_sample_dashboards s
WHERE s.name = 'Grand Prix Results · Sample'
  AND NOT EXISTS (
    SELECT 1 FROM public.bi_dashboards d WHERE d.user_id = u.id AND d.name = s.name
  );
